mapper.select:
SELECT b.NAME as eventType,a.EVENT_LEVEL as eventLevel,a.UNIQUE_CODE as uniqueCode,b.id as eventTypeId,a.ID as eventId, c.NAME as assetName,c.IP as assetIp1,c.IP2 as assetIp2,c.id as assetId, a.EVENT_MSG as eventMsg,a.CREATE_TIME as createTime,a.flag FROM ALARM_EVENT a LEFT JOIN ALARM_EVENT_TYPE b ON a.EVENT_TYPE_ID = b.ID LEFT JOIN ASSET c ON c.ID = a.ASSET_ID
and c.name like concat(concat('%',#{query.assetName}),'%')
and c.EVENT_TYPE_ID = #{query.eventTypeId}
and (c.ip =#{query.assetIp} or c.ip2 =#{query.assetIp} )
and c.ORG_ID = #{query.orgId}
and a.EVENT_LEVEL = #{query.eventLevel}
and a.EVENT_MSG like concat(concat('%',#{query.eventMsg}),'%')
and a.UNIQUE_CODE = #{query.uniqueCode}
and a.EVENT_TYPE_ID = #{query.eventTypeId}
and a.EVENT_TYPE_ID !=1
and a.EVENT_TYPE_ID = 1
and a.EVENT_LEVEL is null
and a.CREATE_TIME >= to_date(#{query.startTime},'YYYY-MM-DD HH24:MI:SS')
and a.CREATE_TIME <= to_date(#{query.endTime},'YYYY-MM-DD HH24:MI:SS')
order by a.${query.orderBy}
order by a.CREATE_TIME
${query.sort}
desc

mapper.update:
update ALARM_EVENT a
set a.EVENT_TYPE_ID=#{eventTypeId},
    a.REPOSITORY_ID=#{repositoryId}
where a.UNIQUE_CODE = #{uniqueCode}

mapper.select:
select *
from ALARM_EVENT
where id = (
    select MAX(id)
    from ALARM_EVENT
    where ASSET_ID = #{assetId}
      and EVENT_TYPE_ID = #{typeId}
      and FLAG = #{flag}
      and UNIQUE_CODE = #{uniqueCode}
)

