mapper.select:
SELECT temp.*
FROM (
         SELECT ROWNUM, t.*
         FROM ALARM_EVENT t
         WHERE ROWNUM < #{end}
           AND t.ASSET_ID = #{assetId}
           AND t.UNIQUE_CODE LIKE 'event:log%'
     ) temp
WHERE ROWNUM >= #{start}
